/*!50003 CREATE*/ /*!50017 DEFINER=`root`@`localhost`*/ /*!50003 TRIGGER update_dates_after_purchase
AFTER INSERT ON purchases
FOR EACH ROW
BEGIN
    UPDATE inventory 
    SET 
        entry_date = NEW.date_purchase,
        exp_date = NEW.exp_date
    WHERE id_drug = NEW.id_drug;
    UPDATE drugs
    SET 
        date_exp = NEW.exp_date
    WHERE id_drug = NEW.id_drug;
END */;;
DELIMITER ;
